'use strict';
const LoadingYard={states:{WAITING_ARRIVAL:'待到厂登记',WAITING_PLAN:'等待创建装车计划',PLANNED:'已创建装车计划',CANCELLED:'已取消'},fields:{trailer_one:'挂车1车牌号',trailer_two:'挂车2车牌号（选填）',driver_name:'司机全名',passport_no:'司机护照号',container_no:'集装箱号（选填）'},
 async page(){const q=new URLSearchParams(location.search),month=q.get('shipment_month')||new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit'}).format(new Date()).slice(0,7),query=new URLSearchParams({shipment_month:month,...(q.get('customer_id')?{customer_id:q.get('customer_id')}: {}),...(q.get('status')?{status:q.get('status')}: {}),...(q.get('arrival_date')?{arrival_date:q.get('arrival_date')}:{})}),data=await API.request('/loading-plans/arrivals?'+query);if(q.has('vehicle_id'))return this.form(data.items.find(r=>r.dispatch_vehicle_id===q.get('vehicle_id')));const master=await Business.load();Router.page('车辆到厂登记',`<div class="business-toolbar yard-tabs"><a class="button primary" href="/loading-plans">车辆到厂登记</a><a class="button secondary" href="/loading-plans/query">装车计划查询</a><span class="yard-step">派车单 → 到厂登记 → 装车计划 → 装车及出库</span></div><div class="yard-counts">${Object.entries(this.states).map(([k,v])=>`<article><span>${v}</span><strong data-no-i18n>${data.items.filter(r=>r.arrival_state===k).length}</strong></article>`).join('')}</div><form id="yard-filter" class="filters"><div class="form-grid"><label>发运月份<input name="shipment_month" type="month" value="${esc(month)}" required></label><label>客户名称<select name="customer_id"><option value="">全部客户</option>${Business.options(master.customers,q.get('customer_id'),'name')}</select></label><label>状态<select name="status"><option value="">全部状态</option>${Object.entries(this.states).map(([key,label])=>`<option value="${key}" ${q.get('status')===key?'selected':''}>${label}</option>`).join('')}</select></label></div><button class="button secondary">查询</button>${Business.can('inventory:export')?'<button type="button" id="yard-export" class="button secondary">导出Excel</button>':''}</form><div class="business-table yard-arrival-table"><table id="cu-arrivals-table"><thead><tr><th>客户 / 销售计划</th><th>发运月份</th><th>车头号</th><th>载重（吨）</th><th>到达时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${data.items.map(r=>`<tr class="${r.arrival_id?'yard-arrived':''}"><td data-no-i18n>${esc(r.customer_name)}<br>${esc(r.sales_plan_code)}</td><td data-no-i18n>${esc(r.shipment_month)}</td><td data-no-i18n>${esc(r.truck_no)}</td><td>${r.capacity_tonnes?Tonnes.format(r.capacity_tonnes):'未提供'}</td><td data-no-i18n>${r.arrived_at?BusinessTime.display(r.arrived_at):'—'}</td><td>${this.states[r.arrival_state]}</td><td>${r.arrival_state==='WAITING_ARRIVAL'&&Business.can('vehicle-arrival:write')||r.arrival_state==='WAITING_PLAN'&&Business.can('vehicle-arrival:write')?`<a class="button secondary" href="/loading-plans?tab=arrivals&${query}&vehicle_id=${r.dispatch_vehicle_id}">${r.arrival_id?'编辑到厂登记':'登记车辆到厂'}</a>`:''}${r.arrival_state==='WAITING_PLAN'&&Business.can('loading-plan:write')?`<a class="button primary" href="/loading-plans/new?sales_plan_id=${r.sales_plan_id}&arrival_id=${r.arrival_id}">创建装车计划</a>`:''}${r.plan_document_id?`<a class="button secondary" href="/loading-plans/orders/${r.plan_document_id}">查看装车计划</a>`:''}</td></tr>`).join('')||'<tr><td colspan="7">该客户发运月份暂无有效派车车辆，请先上传派车单。</td></tr>'}</tbody></table></div>`);LoadingFiltersR9.arrivals($('yard-filter'),master.customers,false);$('yard-filter').onsubmit=e=>{e.preventDefault();Router.go('/loading-plans?tab=arrivals&'+new URLSearchParams(new FormData(e.target)));};},
 async export(query){const b=$('yard-export');b.disabled=true;try{const r=await API.request('/loading-plans/arrivals/export',{method:'POST',body:Object.fromEntries(query),binary:true}),a=document.createElement('a'),url=URL.createObjectURL(r.blob);a.href=url;a.download='Vehicle_Arrivals_CU.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){notify(e.message);}finally{if(b.isConnected)b.disabled=false;}},
 async form(r){if(!Business.can('vehicle-arrival:write'))throw Error('没有车辆到厂登记权限');if(!r||r.cancelled_at||r.plan_document_id)throw Error('车辆已取消、已创建计划或不在当前筛选范围');Router.page('车辆到厂登记',`<div class="lot-context-grid"><article><span>客户名称</span><strong data-no-i18n>${esc(r.customer_name)}</strong></article><article><span>发运月份</span><strong data-no-i18n>${esc(r.shipment_month)}</strong></article><article><span>车头号</span><strong data-no-i18n>${esc(r.truck_no)}</strong></article></div><p>请在停车场核实车辆已到厂且可以装货，再登记实际运输信息。</p><form id="yard-arrival-form" class="user-form"><div class="form-grid"><label>到达时间（卢本巴希）<input name="arrived_at" type="datetime-local" required value="${BusinessTime.input(r.arrived_at||new Date())}"></label>${Object.entries(this.fields).map(([k,label])=>`<label>${label}<input name="${k}" value="${esc(r[k]||(k==='trailer_one'?r.trailer_no||'':''))}" maxlength="${k==='driver_name'?160:k==='container_no'?40:80}" ${['trailer_one','driver_name','passport_no'].includes(k)?'required':''}></label>`).join('')}</div><p id="yard-error" class="error" role="alert"></p><div class="business-toolbar"><button class="button primary">确认到厂并提交</button><a class="button secondary" href="/loading-plans?tab=arrivals&shipment_month=${r.shipment_month}">返回车辆列表</a></div></form>`);$('yard-arrival-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{if(!await OperationConfirm.ask({title:'请确认车辆已到厂并可装货',rows:[['关联车号',r.truck_no],['客户名称',r.customer_name],['发运月份',r.shipment_month]]}))return;await API.request('/loading-plans/arrivals/'+r.dispatch_vehicle_id,{method:'POST',body:{...Object.fromEntries(new FormData(e.target)),arrived_at:BusinessTime.toISO(e.target.elements.arrived_at.value),...(r.arrival_id?{version:r.version}:{})}});await Router.go('/loading-plans?tab=arrivals&shipment_month='+r.shipment_month);notify('已提交到厂登记，等待创建装车计划');}catch(err){$('yard-error').textContent=err.message;}finally{if(e.submitter.isConnected)e.submitter.disabled=false;}};},
 async enhance(id){const form=$('single-plan-form');if(!form||form.querySelector('#yard-arrival-choice'))return;const query=new URLSearchParams(location.search),current=id?await API.request('/loading-plans/unified/documents/'+id):null;const label=document.createElement('label');label.className='yard-arrival-choice';label.innerHTML='<span>已登记到厂车辆</span><select name="arrival_id" id="yard-arrival-choice"><option value="">请选择等待创建计划的车辆</option></select><small id="yard-arrival-help"></small>';form.elements.sales_plan_id.closest('label').after(label);if(!current||current.arrival_required||current.arrival_id)label.querySelector('select').required=true;let rows=[],seq=0;
 const select=label.querySelector('select'),load=async()=>{const n=++seq,planId=form.elements.sales_plan_id.value;select.innerHTML='<option value="">请选择等待创建计划的车辆</option>';if(!planId)return;try{rows=(await API.request('/loading-plans/arrivals?sales_plan_id='+planId)).items.filter(r=>r.arrival_id&&(r.arrival_state==='WAITING_PLAN'||r.arrival_id===current?.arrival_id));if(n!==seq)return;form.operationArrivals=rows;const chosen=current?.arrival_id||query.get('arrival_id');select.innerHTML='<option value="">请选择等待创建计划的车辆</option>'+rows.map(r=>`<option value="${r.arrival_id}" ${chosen===r.arrival_id?'selected':''}>${esc(r.truck_no+' · '+r.shipment_month+' · '+r.driver_name)}</option>`).join('');$('yard-arrival-help').innerHTML=rows.length?'运输及司机信息由到厂登记自动带入。':'暂无已登记到厂的车辆。<a href="/loading-plans?tab=arrivals">查看到厂登记</a>';select.onchange();}catch(e){$('single-plan-error').textContent=e.message;}};
 select.onchange=()=>{const r=rows.find(r=>r.arrival_id===select.value);if(r){form.elements.vehicle_no.value=r.truck_no;form.elements.vehicle_no.readOnly=true;}else{form.elements.vehicle_no.readOnly=!!select.required;if(!current)form.elements.vehicle_no.value='';}};const prior=form.elements.sales_plan_id.onchange;form.elements.sales_plan_id.onchange=async()=>{await prior?.();await load();};await load();
 for(const [field,title] of Object.entries({export_license_no:'许可证记录簿',transporter:'运输商记录簿',destination:'目的地记录簿'})){const input=form.elements[field],wrap=document.createElement('div'),button=document.createElement('button');wrap.className='transport-book-input';input.before(wrap);wrap.append(input);button.type='button';button.className='button secondary';button.textContent='记录簿';button.onclick=()=>this.book(form,field,title);wrap.append(button);}I18n.apply();},
 async book(form,field,title){const plans=(await API.request('/plans')).items,plan=plans.find(p=>p.id===form.elements.sales_plan_id.value);if(!plan){notify('请先选择销售计划');return;}const r=await API.request('/customers/'+plan.customer_id+'/transport-book'),items=r.items.filter(x=>x.field===field);dialog(title,`<p><span>客户名称</span>：<strong data-no-i18n>${esc(plan.customer_name)}</strong></p><div class="transport-book-list">${items.map(i=>`<div class="book-entry"><strong data-no-i18n>${esc(i.value)}</strong><button class="button secondary" data-book-pick="${i.id}" type="button">选择</button>${Business.can('loading-plan:write')?`<button class="button secondary" data-book-edit="${i.id}" type="button">编辑</button><button class="button danger" data-book-delete="${i.id}" type="button">删除</button>`:''}</div>`).join('')||'<p>暂无保存记录</p>'}</div><form id="transport-book-save" class="user-form"><label>保存新记录<input name="value" maxlength="${field==='destination'?1000:160}" required value="${esc(form.elements[field].value)}"></label><p id="transport-book-error" class="error" role="alert"></p><button class="button primary">保存并使用</button></form>`);for(const b of document.querySelectorAll('[data-book-pick]'))b.onclick=()=>{form.elements[field].value=items.find(i=>i.id===b.dataset.bookPick).value;$('dialog').close();};for(const b of document.querySelectorAll('[data-book-edit],[data-book-delete]'))b.onclick=async()=>{const item=items.find(i=>i.id===(b.dataset.bookEdit||b.dataset.bookDelete)),remove=!!b.dataset.bookDelete;let value=item.value;try{if(!await OperationConfirm.ask({title:remove?'请确认删除记录':'编辑记录',rows:[['客户名称',plan.customer_name]],note:'仅影响今后选择，不修改已保存的装车计划及历史装箱单。',comment:!remove,commentRequired:!remove,commentLabel:'记录内容',commentMax:field==='destination'?1000:160,commentValue:value,onComment:v=>value=v}))return;b.disabled=true;await (remove?feedbackRequest:API.request.bind(API))('/customers/'+plan.customer_id+'/transport-book/'+item.id,{method:remove?'DELETE':'PATCH',body:{version:item.version,value}});await this.book(form,field,title);}catch(e){$('transport-book-error').textContent=e.message;}finally{if(b.isConnected)b.disabled=false;}};$('transport-book-save').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const saved=await API.request('/customers/'+plan.customer_id+'/transport-book',{method:'POST',body:{field,value:new FormData(e.target).get('value')}});form.elements[field].value=saved.value;$('dialog').close();notify('记录已保存');}catch(err){$('transport-book-error').textContent=err.message;e.submitter.disabled=false;}};}
};
const yardPlanForm=SinglePlan.form.bind(SinglePlan);SinglePlan.form=async function(id,legacy){await yardPlanForm(id,legacy);await LoadingYard.enhance(id);};
const yardList=Management.list.bind(Management);Management.list=async function(kind){if(kind==='loading'&&location.pathname==='/loading-plans')return LoadingYard.page();await yardList(kind);if(kind==='loading'){const tabs=document.createElement('div');tabs.className='business-toolbar yard-tabs';tabs.innerHTML='<a class="button secondary" href="/loading-plans">车辆到厂登记</a><a class="button primary" href="/loading-plans/query">装车计划查询</a>';$('page-content').prepend(tabs);I18n.apply();}};
const yardInit=Router.init.bind(Router);Router.init=async function(){Router.add(/^\/loading-plans\/query$/,()=>Management.list('loading'));return yardInit();};
const yardPlanDetail=SinglePlan.detail.bind(SinglePlan);SinglePlan.detail=async function(id){await yardPlanDetail(id);const d=await API.request('/loading-plans/unified/documents/'+id);if(d.arrival_transport){const section=document.createElement('section');section.className='lot-summary-detail lp-arrival-transport';section.innerHTML='<h3>到厂运输信息</h3><dl class="lp-fields">'+Object.entries(LoadingYard.fields).map(([k,l])=>'<dt>'+l+'</dt><dd data-no-i18n>'+esc(d.arrival_transport[k]||'—')+'</dd>').join('')+'</dl>';$('page-content').append(section);I18n.apply();}};LoadingPlans.doc=SinglePlan.detail.bind(SinglePlan);

const yardShippingDetail=Shipping.detail.bind(Shipping);Shipping.detail=async function(id){await yardShippingDetail(id);const d=await API.request('/shipping/'+id);if(d.loading_plan?.arrival_id){const form=$('shipping-transport-form');for(const key of Object.keys(LoadingYard.fields))if(form?.elements[key])form.elements[key].readOnly=true;const note=document.createElement('p');note.className='dialog-notice';note.textContent='司机、挂车及集装箱信息来自到厂登记，已与装车计划关联。';form?.before(note);I18n.apply();}};
